DECLARE problem text;
BEGIN
  SELECT string_agg(b.label, ' | ') INTO problem FROM event_tags_batch b
    WHERE (SELECT count(*) FROM public.events e WHERE e.label_fr = b.label) <> 1;
  IF problem IS NOT NULL THEN RAISE EXCEPTION 'Libellé absent ou ambigu, lot refusé : %', problem; END IF;
  SELECT string_agg(b.label, ' | ') INTO problem FROM event_tags_batch b JOIN public.events e ON e.label_fr = b.label JOIN public.event_tags t ON t.event_id = e.id;
  IF problem IS NOT NULL THEN RAISE EXCEPTION 'Événement déjà tagué, lot refusé : %', problem; END IF;
END $guard$;
INSERT INTO public.event_tags (event_id, tag_id, position)
  SELECT e.id, t.tag_id, t.position
  FROM event_tags_batch b
  JOIN public.events e ON e.label_fr = b.label
  CROSS JOIN LATERAL unnest(b.tags) WITH ORDINALITY AS t(tag_id, position);
SELECT count(DISTINCT event_id) AS tagged_events, count(*) AS links FROM public.event_tags;
COMMIT;
